LineContribType* calculate_contributions(unsigned int line_size, unsigned int src_size, double scale_d, const double (*pFilter)(double)) {
    if (line_size == 0 || src_size == 0 || scale_d <= 0 || pFilter == NULL) {
        return NULL;
    }

    // Determine filter width
    int filter_width = (int)(0.5 + 1.5 * scale_d);
    if (filter_width < 1) {
        filter_width = 1;
    }

    // Allocate memory for contributions
    LineContribType* contribs = (LineContribType*)malloc(line_size * sizeof(LineContribType));
    if (contribs == NULL) {
        return NULL;
    }

    for (unsigned int i = 0; i < line_size; i++) {
        double x = (double)i * scale_d;
        int left = (int)x - filter_width;
        int right = (int)x + filter_width;

        // Ensure within source bounds
        left = (left < 0) ? 0 : left;
        right = (right > (int)src_size) ? (int)src_size : right;

        double total_weight = 0.0;
        for (int j = left; j < right; j++) {
            double dx = (double)(j - (int)x);
            contribs[i].weight[j - left] = pFilter(dx);
            total_weight += contribs[i].weight[j - left];
        }

        // Check if total weight is negative
        if (total_weight < 0.0) {
            free(contribs);
            return NULL;
        }

        // Normalize weights
        for (int j = left; j < right; j++) {
            contribs[i].weight[j - left] /= total_weight;
        }
    }

    return contribs;
}

