typedef struct {
    double* weights;
} LineContribType;

typedef double (*interpolation_method)(double);

LineContribType* calculate_contributions(unsigned int line_size, unsigned int src_size, double scale_d, interpolation_method pFilter) {
    if (line_size == 0 || src_size == 0 || scale_d <= 0.0 || pFilter == NULL) {
        return NULL;
    }

    unsigned int filter_width = (unsigned int)(scale_d + 0.5);
    LineContribType* contribs = (LineContribType*)malloc(sizeof(LineContribType));
    if (contribs == NULL) {
        return NULL;
    }

    contribs->weights = (double*)calloc(line_size, sizeof(double));
    if (contribs->weights == NULL) {
        free(contribs);
        return NULL;
    }

    for (unsigned int i = 0; i < line_size; i++) {
        double left = i * scale_d;
        double right = left + scale_d;
        double left_idx = left - filter_width / 2.0;
        double right_idx = right + filter_width / 2.0;

        double total_weight = 0.0;
        for (unsigned int j = 0; j < src_size; j++) {
            if (j >= left_idx && j <= right_idx) {
                double weight = pFilter((double)j - left);
                contribs->weights[i] += weight;
                total_weight += weight;
            }
        }

        if (total_weight < 0.0) {
            free(contribs->weights);
            free(contribs);
            return NULL;
        }

        contribs->weights[i] /= total_weight;
    }

    return contribs;
}

